function renderPackageLimitsInline(data){if($('packageLimitsInline'))return;let box=document.createElement('form');box.id='packageLimitsInline';box.className='panel';box.innerHTML='<h3>حدود الباقات</h3><p class="muted">تعديل عدد المستخدمين والمركبات والفروع والتنبيهات من داخل أسعار الباقات. اترك الخانة فارغة لعدم وضع حد.</p><div class="cards">'+Object.entries(data).map(([plan,values])=>'<div class="panel"><h4>'+esc(pkg[plan]||plan)+'</h4>'+[['users','عدد المستخدمين'],['vehicles','عدد المركبات'],['branches','عدد الفروع'],['organization_notifications','تنبيهات المؤسسة'],['employee_notifications','تنبيهات الموظفين']].map(([resource,label])=>'<label>'+label+'<input type="number" min="0" max="100000" step="1" data-plan="'+esc(plan)+'" data-resource="'+resource+'" value="'+(values[resource]??'')+'" placeholder="دون حد"></label>').join('')+'</div>').join('')+'</div><button class="primary" type="submit">حفظ حدود الباقات</button>';box.onsubmit=async e=>{e.preventDefault();if(!confirm('حفظ حدود الباقات؟ لن تُحذف البيانات الموجودة.'))return;let payload={};box.querySelectorAll('input').forEach(input=>{let p=input.dataset.plan;payload[p]??={};payload[p][input.dataset.resource]=input.value===''?null:Number(input.value)});let b=e.submitter;b.disabled=true;try{let d=await fetch('/owner/api/package-limits',{method:'PUT',headers:{'Content-Type':'application/json','X-Owner-Key':ownerKey},body:JSON.stringify(payload),cache:'no-store'}),result=await d.json();if(!d.ok)throw Error(result.error||'تعذر الحفظ');renderPackageLimitsInline(result);flash('تم حفظ حدود الباقات');}catch(err){flash(err.message)}finally{b.disabled=false}};$('content').append(box)}
