   const b=(name,text,kind='')=>'<button class="'+kind+'" onclick="khdoomAiTaskAction('+x.id+',\''+name+'\')">'+text+'</button>';
   if(x.status==='queued')return b('start','بدء الفحص','primary')+b('skip','لم يُنفذ');
