 [title,mode,bar,text,font,scale,q('adsNewLogoPosition')].forEach(x=>x.addEventListener('input',render));file.addEventListener('change',async()=>{if(file.files[0]){imageData=await readImageData(file.files[0]);render()}});document.querySelectorAll('[data-ads-duration]').forEach(b=>b.onclick=()=>{seconds=Math.max(1,Math.min(30,seconds+Number(b.dataset.adsDuration)));render()});
