function adsNewCreateMarkup(){return '<div class="ads-new-create"><section class="ads-new-editor"><div class="ads-new-row"><label>نوع الإعلان<select id="adsNewMode"><option value="logo_text">شعار + نص</option><option value="full_image">صورة كاملة</option></select></label><label>النص الرئيسي<input id="adsNewTitle" value="معًا نصنع مستقبل أفضل" maxlength="100"></label></div><div class="ads-new-row"><label>نص إضافي اختياري<input id="adsNewSubtitle" placeholder="اكتب نصًا إضافيًا أو اتركه فارغًا" maxlength="100"></label><label>إضافة نص آخر<button type="button" id="adsNewAddText">＋ إضافة نص</button></label></div><div id="adsNewExtraTexts"></div><div class="ads-new-row"><label>لون الخط<input id="adsNewTextColor" type="color" value="#ffffff"></label><label>لون الشريط<input id="adsNewBarColor" type="color" value="#0875e8"></label><label>حجم الخط<input id="adsNewFontSize" type="range" min="14" max="48" value="28"><output id="adsNewFontSizeOut">28</output></label></div><div class="ads-new-row"><label class="ads-upload">صورة / شعار<input id="adsNewImage" type="file" accept="image/png,image/jpeg,image/webp"><span>إضافة صورة أو شعار</span></label><label>موضع الشعار<select id="adsNewLogoPosition"><option value="left">يسار</option><option value="right">يمين</option></select></label></div><div class="ads-new-row"><label>عرض الصورة<input id="adsNewImageWidth" type="range" min="40" max="2000" value="120"><output id="adsNewImageWidthOut">120</output></label><label>ارتفاع الصورة<input id="adsNewImageHeight" type="range" min="30" max="600" value="100"><output id="adsNewImageHeightOut">100</output></label></div><div class="ads-new-row ads-duration-row"><label>مدة ظهور الشريط<div class="ads-duration-control"><button type="button" data-ads-duration="-1">−</button><output id="adsNewDurationOut">10 ثانية</output><button type="button" data-ads-duration="1">＋</button></div></label></div><div class="ads-new-actions"><button class="primary" type="button" data-ads-new-submit="save">حفظ</button><button class="primary" type="button" data-ads-new-submit="publish">نشر</button></div></section><section class="ads-new-preview"><div class="ads-new-preview-head"><h3>شريط الإعلان المباشر</h3><span>ثابت أثناء التمرير · 1200 × 300 (4:1)</span></div><div class="ads-new-banner" id="adsNewBanner"><div class="ads-new-selected-image" id="adsNewFullBox" hidden><span class="ads-handle w">↔</span><span class="ads-handle e">↔</span><span class="ads-handle n">↕</span><span class="ads-handle s">↕</span><img id="adsNewFullImage" alt="صورة الإعلان"></div><div class="ads-new-selected-image" id="adsNewLogoBox" hidden><span class="ads-handle w">↔</span><span class="ads-handle e">↔</span><span class="ads-handle n">↕</span><span class="ads-handle s">↕</span><img id="adsNewLogo" alt="شعار الإعلان"></div><div id="adsNewTextLayers"><strong id="adsNewCopyTitle" data-ads-text="title">معًا نصنع مستقبل أفضل</strong><span id="adsNewCopySubtitle" data-ads-text="subtitle"></span></div></div></section></div>'}
function bindAdsNewCreate(){
 const q=id=>document.getElementById(id),banner=q('adsNewBanner'),mode=q('adsNewMode'),title=q('adsNewTitle'),subtitle=q('adsNewSubtitle'),bar=q('adsNewBarColor'),text=q('adsNewTextColor'),font=q('adsNewFontSize'),width=q('adsNewImageWidth'),height=q('adsNewImageHeight'),fullBox=q('adsNewFullBox'),full=q('adsNewFullImage'),logoBox=q('adsNewLogoBox'),logo=q('adsNewLogo'),copy=q('adsNewTextLayers'),file=q('adsNewImage'),duration=q('adsNewDurationOut'),extras=q('adsNewExtraTexts');let imageData='',seconds=10,extraInputs=[];
 const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
 const addText=()=>{let id='extra_'+Date.now(),input=document.createElement('input');input.id=id;input.placeholder='نص إضافي';input.maxLength=100;input.className='ads-extra-input';input.dataset.extra='1';let label=document.createElement('label');label.textContent='نص إضافي';label.append(input);extras.append(label);extraInputs.push(input);input.addEventListener('input',render);render()};
 const textPosition=new WeakMap();
 const dragText=el=>{el.onpointerdown=e=>{e.preventDefault();let r=banner.getBoundingClientRect(),move=ev=>{el.style.left=clamp((ev.clientX-r.left)/r.width*100,5,95)+'%';el.style.top=clamp((ev.clientY-r.top)/r.height*100,8,92)+'%'},up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)}};
 const bindResize=box=>box.querySelectorAll('.ads-handle').forEach(handle=>handle.onpointerdown=e=>{e.preventDefault();e.stopPropagation();handle.setPointerCapture?.(e.pointerId);let startX=e.clientX,startY=e.clientY,rect=box.getBoundingClientRect(),parent=banner.getBoundingClientRect(),baseW=rect.width,baseH=rect.height,baseLeft=rect.left-parent.left,baseTop=rect.top-parent.top;let move=ev=>{let dx=ev.clientX-startX,dy=ev.clientY-startY,w=baseW,h=baseH,left=baseLeft,top=baseTop;if(handle.classList.contains('e'))w=baseW+dx;if(handle.classList.contains('w')){w=baseW-dx;left=baseLeft+dx}if(handle.classList.contains('s'))h=baseH+dy;if(handle.classList.contains('n')){h=baseH-dy;top=baseTop+dy}w=clamp(w,40,2000);h=clamp(h,30,600);left=clamp(left,0,Math.max(0,parent.width-w));top=clamp(top,0,Math.max(0,parent.height-h));box.style.width=w+'px';box.style.height=h+'px';box.style.left=left+'px';box.style.right='auto';box.style.top=top+'px';box.style.transform='none';width.value=Math.round(w);height.value=Math.round(h);q('adsNewImageWidthOut').value=width.value;q('adsNewImageHeightOut').value=height.value};let up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up)});
 const render=()=>{banner.style.background=bar.value;banner.style.color=text.value;q('adsNewFontSizeOut').value=font.value;q('adsNewImageWidthOut').value=width.value;q('adsNewImageHeightOut').value=height.value;duration.textContent=seconds+' ثانية';const fullMode=mode.value==='full_image';fullBox.hidden=!fullMode||!imageData;logoBox.hidden=fullMode||!imageData;full.src=imageData;logo.src=imageData;if(fullMode){fullBox.style.width='100%';fullBox.style.height='100%';fullBox.style.left='0';fullBox.style.top='0';fullBox.style.transform='none'}else{fullBox.style.width=width.value+'px';fullBox.style.height=height.value+'px';fullBox.style.left='50%';fullBox.style.top='50%';fullBox.style.transform='translate(-50%,-50%)'}logoBox.style.width=width.value+'px';logoBox.style.height=height.value+'px';logoBox.style.left=q('adsNewLogoPosition').value==='right'?'auto':'18px';logoBox.style.right=q('adsNewLogoPosition').value==='right'?'18px':'auto';logoBox.style.top='50%';logoBox.style.transform='translateY(-50%)';copy.style.display=fullMode?'none':'flex';q('adsNewCopyTitle').textContent=title.value||'';q('adsNewCopySubtitle').textContent=subtitle.value||'';q('adsNewCopyTitle').style.fontSize=font.value+'px';q('adsNewCopySubtitle').style.fontSize=Math.max(12,Number(font.value)-5)+'px';extras.querySelectorAll('input').forEach((input,i)=>{let node=q('adsTextExtra_'+i);if(!node){node=document.createElement('span');node.id='adsTextExtra_'+i;node.dataset.adsText='extra';copy.append(node);dragText(node)}node.textContent=input.value;node.style.display=input.value?'block':'none';node.style.fontSize=Math.max(12,Number(font.value)-4)+'px'});dragText(q('adsNewCopyTitle'));dragText(q('adsNewCopySubtitle'));bindResize(fullBox);bindResize(logoBox)};
 [mode,title,subtitle,bar,text,font,width,height,q('adsNewLogoPosition')].forEach(x=>x.addEventListener('input',render));q('adsNewAddText').onclick=addText;file.addEventListener('change',async()=>{if(file.files[0]){imageData=await readImageData(file.files[0]);render()}});document.querySelectorAll('[data-ads-duration]').forEach(b=>b.onclick=()=>{seconds=clamp(seconds+Number(b.dataset.adsDuration),1,30);render()});document.querySelectorAll('[data-ads-new-submit]').forEach(btn=>btn.onclick=async()=>{try{btn.disabled=true;let messages=[title.value,subtitle.value,...extraInputs.map(x=>x.value)].map(x=>String(x||'').trim()).filter(Boolean);await api('/owner/api/platform-ads','POST',{title:title.value,message:messages.join('\n'),imageData:imageData||'',durationDays:30,displaySeconds:seconds,textColor:text.value,barColor:bar.value,textAlign:'right',fontSize:Number(font.value),imageWidth:Number(width.value),imageHeight:Number(height.value),status:btn.dataset.adsNewSubmit==='publish'?'published':'draft'});flash(btn.dataset.adsNewSubmit==='publish'?'تم نشر الإعلان':'تم حفظ الإعلان');await render()}catch(err){flash(err.message)}finally{btn.disabled=false}});render();
}
